def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    try:
        return value.isoformat()
    except AttributeError:
        raise TypeError(f"Expected a datetime.time instance, got {type(value).__name__}")

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        raise ValueError("value cannot be None")
    try:
        lat = getattr(value, 'lat')
        lon = getattr(value, 'lon')
        time = getattr(value, 'time')
    except AttributeError as exc:
        raise TypeError("value must have 'lat', 'lon', and 'time' attributes") from exc
    if hasattr(time, 'isoformat'):
        time_str = time.isoformat()
    else:
        time_str = str(time)
    return {'lat': lat, 'lon': lon, 'time': time_str}

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Prefer internal _keys dictionary if present
        if hasattr(self, "_keys") and isinstance(self._keys, dict):
            key_names = []
            for key_obj in self._keys.values():
                # If key object has a 'name' attribute, use it; otherwise use the key itself
                if hasattr(key_obj, "name"):
                    key_names.append(key_obj.name)
                else:
                    key_names.append(key_obj)
            return key_names

        # Fallback: if the instance has a 'keys' attribute that is a list/tuple
        if hasattr(self, "keys") and isinstance(self.keys, (list, tuple)):
            return list(self.keys)

        # If no keys are stored, return an empty list
        return []

    except Exception:
        # In case of any unexpected error, return an empty list to avoid breaking callers
        return []

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Retrieve the mapping of handlers defined on the class.
    # Subclasses may override this attribute.
    handlers = getattr(cls, "_protocol_handlers", {})
    if not isinstance(handlers, dict):
        # If the attribute exists but is not a dict, treat as empty.
        handlers = {}

    # If no specific version requested, return a copy of all handlers.
    if protocol_version is None:
        return handlers.copy()

    # Validate the protocol_version argument.
    if not isinstance(protocol_version, tuple):
        raise TypeError(
            f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
        )
    if len(protocol_version) != 2:
        raise TypeError(
            f"protocol_version tuple must contain exactly two elements, got {len(protocol_version)}"
        )
    if not all(isinstance(v, int) for v in protocol_version):
        raise TypeError(
            "All elements of protocol_version must be integers"
        )

    # Return the handler for the requested version if it exists.
    if protocol_version in handlers:
        return {protocol_version: handlers[protocol_version]}
    return {}

def index(self, key):
    """Return the index of the given item."""
    try:
        # Prefer a dedicated lookup dictionary if available
        if hasattr(self, "_index_lookup") and isinstance(self._index_lookup, dict):
            if key in self._index_lookup:
                return self._index_lookup[key]
            raise KeyError
        # Fallback to a list/tuple of keys
        if hasattr(self, "_index") and isinstance(self._index, (list, tuple)):
            return self._index.index(key)
        # As a last resort, try the underlying data container
        if hasattr(self, "_data") and isinstance(self._data, (list, tuple)):
            return self._data.index(key)
        raise KeyError(f"Key {key!r} not found")
    except (ValueError, TypeError):
        raise KeyError(f"Key {key!r} not found")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no keys provided, return all values
    if not keys:
        try:
            return list(self.values())
        except AttributeError:
            # Fallback to items if values() is not available
            return [v for _, v in self.items()]

    # Get ordered list of values
    try:
        values_list = list(self.values())
    except AttributeError:
        values_list = [v for _, v in self.items()]

    result = []
    for k in keys:
        if isinstance(k, int):
            try:
                result.append(values_list[k])
            except IndexError as e:
                raise IndexError(
                    f"Index {k} out of range for values list of length {len(values_list)}"
                ) from e
        else:
            if k in self:
                result.append(self[k])
            else:
                raise KeyError(f"Key {k} not found in record")
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # If no specific keys are requested, return all fields
    if not keys:
        return dict(zip(self._keys, self._values))

    result = {}
    for k in keys:
        if isinstance(k, int):
            # Handle integer index
            if k < 0 or k >= len(self._values):
                raise IndexError(f"Index {k} out of bounds")
            key_name = self._keys[k]
            result[key_name] = self._values[k]
        else:
            # Handle key name
            if k in self._keys:
                idx = self._keys.index(k)
                result[k] = self._values[idx]
            else:
                result[k] = None
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    # Ensure there is a data buffer to work with
    if not hasattr(self, 'data') or self.data is None:
        raise ValueError("No data buffer available to pop from.")
    # Ensure the buffer has at least two bytes
    if len(self.data) < 2:
        raise ValueError("Insufficient data: need at least 2 bytes to pop a u16.")
    # Extract the last two bytes
    last_two = self.data[-2:]
    # Remove the last two bytes from the buffer
    try:
        # If data is a mutable bytearray, delete in place
        if isinstance(self.data, bytearray):
            del self.data[-2:]
        else:
            # For immutable types like bytes, create a new slice
            self.data = self.data[:-2]
    except Exception as exc:
        raise RuntimeError(f"Failed to remove bytes from data buffer: {exc}") from exc
    # Convert the two bytes to an unsigned 16-bit integer (big-endian)
    try:
        return int.from_bytes(last_two, byteorder='big', signed=False)
    except Exception as exc:
        raise ValueError(f"Failed to interpret bytes as u16: {exc}") from exc

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode is None:
        mode = "WRITE"
    if not isinstance(mode, str) or mode not in ("READ", "WRITE"):
        raise ValueError("mode must be 'READ' or 'WRITE'")
    # Validate bookmarks
    if bookmarks is not None:
        try:
            iter(bookmarks)
        except TypeError:
            raise ValueError("bookmarks must be an iterable")
    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise ValueError("metadata must be a dict")
    # Validate timeout
    if timeout is not None and not isinstance(timeout, (int, float)):
        raise ValueError("timeout must be a number")
    # Validate db
    if db is not None and not isinstance(db, str):
        raise ValueError("db must be a string")
    # Validate imp_user
    if imp_user is not None and not isinstance(imp_user, str):
        raise ValueError("imp_user must be a string")
    # Validate dehydration_hooks
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise ValueError("dehydration_hooks must be a dict")
        for key, func in dehydration_hooks.items():
            if not callable(func):
                raise ValueError("dehydration_hooks values must be callable")
    # Validate hydration_hooks
    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise ValueError("hydration_hooks must be a dict")
        for key, func in hydration_hooks.items():
            if not callable(func):
                raise ValueError("hydration_hooks values must be callable")
    # Build the BEGIN message
    message = {"type": "BEGIN", "mode": mode}
    if bookmarks is not None:
        message["bookmarks"] = list(bookmarks)
    if metadata is not None:
        message["metadata"] = metadata
    if timeout is not None:
        message["timeout"] = timeout
    if db is not None:
        message["db"] = db
    if imp_user is not None:
        message["imp_user"] = imp_user
    # Store hooks on the instance for later use
    if dehydration_hooks is not None:
        self._dehydration_hooks = dehydration_hooks
    if hydration_hooks is not None:
        self._hydration_hooks = hydration_hooks
    # Ensure the output queue exists and append the message
    if not hasattr(self, "_output_queue"):
        self._output_queue = []
    self._output_queue.append(message)
    # Return a Response object with the message and any handlers
    return Response(message, **handlers)

def point_type(name, fields, srid_map):
    # type: (str, Iterable[str], Mapping[int, Any]) -> type
    """Dynamically create a Point subclass."""
    import keyword
    from collections.abc import Mapping, Iterable
    try:
        from shapely.geometry import Point
    except Exception as exc:
        raise ImportError("shapely.geometry.Point is required") from exc

    # Validate name
    if not isinstance(name, str):
        raise TypeError(f"name must be a string, got {type(name).__name__}")
    if not name.isidentifier():
        raise ValueError(f"name must be a valid identifier: {name!r}")
    if keyword.iskeyword(name):
        raise ValueError(f"name must not be a keyword: {name!r}")

    # Validate fields
    if not isinstance(fields, Iterable):
        raise TypeError(f"fields must be an iterable, got {type(fields).__name__}")
    seen = set()
    field_names = []
    for f in fields:
        if not isinstance(f, str):
            raise TypeError(f"field names must be strings, got {type(f).__name__}")
        if not f.isidentifier():
            raise ValueError(f"field name must be a valid identifier: {f!r}")
        if keyword.iskeyword(f):
            raise ValueError(f"field name must not be a keyword: {f!r}")
        if f in seen:
            raise ValueError(f"duplicate field name: {f!r}")
        seen.add(f)
        field_names.append(f)

    # Validate srid_map
    if srid_map is None:
        srid_map = {}
    if not isinstance(srid_map, Mapping):
        raise TypeError(f"srid_map must be a mapping, got {type(srid_map).__name__}")

    namespace = {
        'SRID_MAP': dict(srid_map),
        '__slots__': tuple(field_names),
    }

    def __init__(self, x, y, *args, **kwargs):
        super(self.__class__, self).__init__(x, y, *args)
        for key in field_names:
            setattr(self, key, kwargs.get(key))

    namespace['__init__'] = __init__

    # Create the subclass
    cls = type(name, (Point,), namespace)
    return cls

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    s = s.strip()
    if not s:
        return (0,)
    # Strip leading 'v' or 'V' if present
    if s.lower().startswith('v'):
        s = s[1:]
    parts = s.split('.')
    nums = []
    for part in parts:
        i = 0
        while i < len(part) and part[i].isdigit():
            i += 1
        if i > 0:
            try:
                nums.append(int(part[:i]))
            except ValueError:
                # Skip parts that cannot be converted to int
                pass
    if not nums:
        return (0,)
    return tuple(nums)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import sys

    if not cmd:
        return cmd

    # Convert to a mutable list
    cmd_list = list(cmd)

    # Handle shebang lines in scripts
    first = cmd_list[0]
    if isinstance(first, str) and os.path.isfile(first):
        try:
            with open(first, 'r', encoding='utf-8', errors='ignore') as f:
                first_line = f.readline()
            if first_line.startswith('#!'):
                # Extract interpreter from shebang
                parts = first_line[2:].strip().split()
                if parts:
                    interpreter = parts[0]
                    # Quote interpreter if it contains spaces
                    if ' ' in interpreter and not (interpreter.startswith('"') and interpreter.endswith('"')):
                        interpreter = f'"{interpreter}"'
                    # Replace the script with the interpreter
                    cmd_list[0] = interpreter
                    # Insert the script path as the first argument
                    cmd_list.insert(1, first)
        except Exception:
            # If any error occurs (e.g., permission), ignore and keep original
            pass

    # Quote any argument that contains spaces and is not already quoted
    for idx, arg in enumerate(cmd_list):
        if isinstance(arg, str) and ' ' in arg:
            if not (arg.startswith('"') and arg.endswith('"')):
                cmd_list[idx] = f'"{arg}"'

    return tuple(cmd_list)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not callable(timer):
        raise TypeError("timer must be a callable returning a monotonic time value")
    if not isinstance(ttl, (int, float)) or ttl < 0:
        raise ValueError("ttl must be a non-negative number")

    def _make_key(args, kwargs, typed):
        key = args
        if kwargs:
            # sort kwargs to ensure deterministic order
            key += tuple(sorted(kwargs.items()))
        if typed:
            key += tuple(type(v) for v in args)
            if kwargs:
                key += tuple(type(v) for _, v in sorted(kwargs.items()))
        return key

    def decorator(func):
        cache = collections.OrderedDict()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            now = timer()
            if key in cache:
                value, timestamp = cache[key]
                if now - timestamp < ttl:
                    # Move to end to mark as recently used
                    cache.move_to_end(key)
                    return value
                # expired
                del cache[key]
            # compute new value
            result = func(*args, **kwargs)
            cache[key] = (result, now)
            cache.move_to_end(key)
            if len(cache) > maxsize:
                # pop least recently used item
                cache.popitem(last=False)
            return result

        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")

    def decorator(func):
        cache = {}
        freq = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Build a hashable key from args and kwargs
            key = args
            if kwargs:
                # Sort keyword arguments to ensure consistent ordering
                kw_items = tuple(sorted(kwargs.items()))
                key = key + kw_items

            if typed:
                # Include the type of each argument in the key
                new_key = []
                for v in key:
                    if isinstance(v, tuple) and len(v) == 2 and isinstance(v[0], str):
                        # Keyword argument: keep the key name and include type of value
                        k, val = v
                        new_key.append((k, (val, type(val))))
                    else:
                        new_key.append((v, type(v)))
                key = tuple(new_key)

            if key in cache:
                freq[key] += 1
                return cache[key]

            # Compute the result and store it
            result = func(*args, **kwargs)
            cache[key] = result
            freq[key] = 1

            # Evict least frequently used item if cache exceeds maxsize
            if len(cache) > maxsize:
                min_freq = min(freq.values())
                # Find the first key with the minimum frequency
                for evict_key in list(freq):
                    if freq[evict_key] == min_freq:
                        del cache[evict_key]
                        del freq[evict_key]
                        break

            return result

        return wrapper

    return decorator

def popitem(self):
        """Remove and return the `(key, value)` pair first inserted."""
        try:
            # Get the first key in insertion order
            first_key = next(iter(self))
        except StopIteration:
            # The dictionary is empty
            raise KeyError('dict is empty')
        # Remove the key and get its value
        value = dict.pop(self, first_key)
        return (first_key, value)

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    # Ensure the underlying storage exists and is a dictionary
    if not hasattr(self, "_value") or not isinstance(self._value, dict):
        raise AttributeError("The object does not contain a dictionary named '_value'")

    # Validate key is hashable
    try:
        hash(key)
    except TypeError as exc:
        raise TypeError(f"Key {key!r} is not hashable") from exc

    # Perform the setdefault operation
    try:
        if key in self._value:
            return self._value[key]
        self._value[key] = default
        return default
    except Exception as exc:
        raise RuntimeError(f"Error setting default for key {key!r}") from exc

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default
    except TypeError:
        # key is not hashable or other type error
        return default
    # Other exceptions are propagated to the caller.

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    if not callable(cache):
        raise TypeError("cache must be a callable returning a cache object")
    if not callable(key):
        raise TypeError("key must be a callable that returns a hashable key")
    if lock is not None and not callable(lock):
        raise TypeError("lock must be None or a callable returning a context manager")
    def decorator(method):
        if not callable(method):
            raise TypeError("decorated object must be callable")
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                try:
                    k = key(*args, **kwargs)
                except Exception:
                    k = args
                try:
                    return c[k]
                except (KeyError, TypeError):
                    pass
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except Exception:
                    pass
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                try:
                    k = key(*args, **kwargs)
                except Exception:
                    k = args
                try:
                    with lock(self):
                        return c[k]
                except (KeyError, TypeError):
                    pass
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except Exception:
                    pass
                return v
        wrapper.__name__ = method.__name__
        wrapper.__doc__ = method.__doc__
        wrapper.__dict__.update(method.__dict__)
        return wrapper
    return decorator

def extostr(cls, e, max_level=30, max_path_level=5):
    import traceback, os
    if not isinstance(e, BaseException):
        return str(e)
    lines = [f"{e.__class__.__name__}: {e}"]
    tb = e.__traceback__
    if tb:
        frames = traceback.extract_tb(tb)
        if len(frames) > max_level:
            frames = frames[-max_level:]
        for frame in frames:
            filename = frame.filename
            parts = filename.split(os.sep)
            if len(parts) > max_path_level:
                filename = os.sep.join(['...'] + parts[-max_path_level:])
            lines.append(f'  File "{filename}", line {frame.lineno}, in {frame.name}')
            if frame.line:
                lines.append(f'    {frame.line.strip()}')
    cause = e.__cause__ or e.__context__
    while cause:
        lines.append(f"Caused by {cause.__class__.__name__}: {cause}")
        tb = cause.__traceback__
        if tb:
            frames = traceback.extract_tb(tb)
            if len(frames) > max_level:
                frames = frames[-max_level:]
            for frame in frames:
                filename = frame.filename
                parts = filename.split(os.sep)
                if len(parts) > max_path_level:
                    filename = os.sep.join(['...'] + parts[-max_path_level:])
                lines.append(f'  File "{filename}", line {frame.lineno}, in {frame.name}')
                if frame.line:
                    lines.append(f'    {frame.line.strip()}')
        cause = cause.__cause__ or cause.__context__
    return "\n".join(lines)

def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    # Validate input
    if not isinstance(file_name, str) or not file_name.strip():
        return False
    try:
        return os.path.isfile(file_name)
    except Exception:
        # Any error (e.g., permission, invalid path) results in False
        return False

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    # Try to use zope.interface's directlyProvidedBy if available
    try:
        from zope.interface import directlyProvidedBy as _original
        return _original(object)
    except Exception:
        # Fallback: check for __provides__ attribute on the object or its class
        try:
            provides = getattr(object, "__provides__", None)
            if provides is not None:
                return provides
        except Exception:
            pass
        # Return an empty declaration if we cannot determine the interfaces
        try:
            from zope.interface.interfaces import IDeclaration
            return IDeclaration()
        except Exception:
            # As a last resort, return an empty mapping
            return {}

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Handle None or non-iterable inputs gracefully
    if sequence is None:
        return output

    # If the sequence is a class with a Broken base, return it as is
    try:
        if Broken in getattr(sequence, "__bases__", ()):
            return [sequence]
    except NameError:
        # Broken not defined; ignore this check
        pass

    cls = sequence.__class__
    try:
        # Check if the class is an interface or implements spec
        if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
            output.append(sequence)
        else:
            # Assume sequence is iterable and recurse
            for v in sequence:
                _normalizeargs(v, output)
    except NameError:
        # If InterfaceClass or zope not available, fall back to generic handling
        try:
            for v in sequence:
                _normalizeargs(v, output)
        except Exception:
            # Not iterable; just append the value
            output.append(sequence)
    except Exception:
        # Any other exception: append the value to avoid silent failures
        output.append(sequence)

    return output

def _should_attempt_c_optimizations():
    import os, sys
    pure_python = os.getenv('PURE_PYTHON')
    if pure_python is not None:
        if pure_python.lower() in ('1', 'true', 'yes', 'on'):
            return False
    try:
        if sys.implementation.name == 'pypy':
            return False
    except AttributeError:
        if hasattr(sys, 'pypy_version_info'):
            return False
    return True

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    return False

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset context
    self.context = {}

    # Reinitialize bins
    try:
        # If an initial value is provided, use it to reset existing bins
        if hasattr(self, "initial_value") and self.initial_value is not None:
            if isinstance(self.bins, list):
                self.bins = [self.initial_value for _ in self.bins]
            else:
                # Try to broadcast the value if bins is array-like
                try:
                    self.bins[:] = self.initial_value
                except Exception:
                    self.bins = self.initial_value
        else:
            # Fall back to make_bins if available
            make_bins = getattr(self, "make_bins", None)
            if callable(make_bins):
                self.bins = make_bins()
            else:
                # If no make_bins, clear bins
                self.bins = []
    except AttributeError:
        # If bins attribute does not exist, create an empty list
        self.bins = []
    return None

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    # Find the attribute that holds error indices
    source_attrs = ("err_indices", "error_indices", "errors")
    data = None
    for attr in source_attrs:
        if hasattr(self, attr):
            data = getattr(self, attr)
            break
    if data is None:
        raise AttributeError(
            "No error indices attribute found on the object"
        )

    # Ensure the data is a mapping from coordinate names to indices
    if not isinstance(data, dict):
        raise TypeError(
            "Error indices attribute must be a dict mapping coordinate names to indices"
        )

    if coord_name not in data:
        raise KeyError(f"Coordinate '{coord_name}' not found in error indices")

    value = data[coord_name]

    # Handle None (no errors)
    if value is None:
        return []

    # If the value is already a list or tuple of indices, return it
    if isinstance(value, (list, tuple)):
        return list(value)

    # If the value is a set of indices, return a list
    if isinstance(value, set):
        return list(value)

    # If the value is a dict mapping indices to error values, return the keys
    if isinstance(value, dict):
        return list(value.keys())

    # If the value is a boolean mask or numeric array, try to extract indices
    try:
        # NumPy array or similar with nonzero()
        if hasattr(value, "nonzero"):
            return list(value.nonzero()[0])
        # Iterable (e.g., list of booleans)
        if hasattr(value, "__iter__"):
            return [i for i, v in enumerate(value) if v]
    except Exception:
        pass

    # If the value is a scalar (int or float), return it as a single-element list
    if isinstance(value, (int, float)):
        return [value]

    # If we reach here, the type is unsupported
    raise TypeError(f"Unsupported type for error indices: {type(value)}")

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert bins to a NumPy array
    bins_arr = np.asarray(bins)
    # Handle empty or scalar bins
    if bins_arr.size == 0:
        return 0.0
    if bins_arr.ndim == 0:
        return float(bins_arr)

    # Helper to validate 1D edges
    def _validate_1d_edges(edges_arr):
        if edges_arr.ndim != 1:
            raise ValueError("edges must be a 1D array")
        if len(edges_arr) < 2:
            raise ValueError("edges must contain at least two values")
        return edges_arr

    # Case 1: edges is a single array (1D histogram)
    if isinstance(edges, np.ndarray):
        edges_arr = _validate_1d_edges(edges)
        if bins_arr.ndim != 1:
            raise ValueError("bins must be 1D when edges is 1D")
        if len(bins_arr) != len(edges_arr) - 1:
            raise ValueError("bins length does not match edges")
        widths = np.diff(edges_arr)
        return float(np.sum(bins_arr * widths))

    # Case 2: edges is a sequence of arrays (multi‑dimensional histogram)
    if isinstance(edges, (list, tuple)):
        edges_arrs = [np.asarray(e) for e in edges]
        ndim = len(edges_arrs)
        if ndim == 0:
            raise ValueError("edges sequence must contain at least one array")
        # Validate each edge array
        for e in edges_arrs:
            if e.ndim != 1:
                raise ValueError("each element of edges must be a 1D array")
            if len(e) < 2:
                raise ValueError("each edge array must contain at least two values")
        # Expected shape of bins
        expected_shape = tuple(len(e) - 1 for e in edges_arrs)
        if bins_arr.shape != expected_shape:
            raise ValueError("bins shape does not match edges")
        # Compute widths per dimension
        widths = [np.diff(e) for e in edges_arrs]
        # Broadcast widths to match bins shape
        bin_widths = widths[0].reshape([len(widths[0])] + [1] * (ndim - 1))
        for i in range(1, ndim):
            shape = [1] * i + [len(widths[i])] + [1] * (ndim - i - 1)
            bin_widths = bin_widths * widths[i].reshape(shape)
        return float(np.sum(bins_arr * bin_widths))

    # Unsupported edges format
    raise ValueError("edges must be a 1D array or a sequence of 1D arrays")

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # Direct instance check
        if isinstance(seq, FillRequest):
            return True
        # Exclude Source sequences
        if isinstance(seq, Source):
            return False
        # Iterate over sequence to find a FillRequest element
        for item in seq:
            if isinstance(item, FillRequest):
                return True
        return False
    except TypeError:
        # seq is not iterable
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, "fill", None)) and callable(getattr(obj, "request", None))
    except Exception:
