    except Exception:
        return False

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    try:
        weight = float(weight)
    except Exception:
        raise TypeError("weight must be a numeric scalar")

    # Ensure histogram edges and counts exist
    if not hasattr(self, "edges") or not hasattr(self, "counts"):
        raise AttributeError("Histogram must have 'edges' and 'counts' attributes")

    # Convert coordinate to array
    try:
        coord_arr = np.asarray(coord)
    except Exception:
        raise TypeError("coord must be array-like")

    # 1D histogram
    if isinstance(self.edges, np.ndarray):
        # Scalar coordinate
        if coord_arr.ndim == 0:
            if coord_arr < self.edges[0] or coord_arr > self.edges[-1]:
                return
            idx = np.searchsorted(self.edges, coord_arr, side="right") - 1
            if idx < 0 or idx >= len(self.counts):
                return
            self.counts[idx] += weight
        # Array of coordinates
        else:
            flat = coord_arr.ravel()
            idxs = np.searchsorted(self.edges, flat, side="right") - 1
            valid = (idxs >= 0) & (idxs < len(self.counts))
            if np.any(valid):
                np.add.at(self.counts, idxs[valid], weight)
    # Multi‑dimensional histogram
    else:
        if not isinstance(self.edges, (list, tuple)):
            raise AttributeError("Histogram edges must be a list or tuple of arrays")
        if coord_arr.ndim != 1 or coord_arr.size != len(self.edges):
            raise ValueError("coord must be a sequence of length equal to number of dimensions")
        idxs = []
        for dim, edge in enumerate(self.edges):
            if coord_arr[dim] < edge[0] or coord_arr[dim] > edge[-1]:
                return
            idx = np.searchsorted(edge, coord_arr[dim], side="right") - 1
            if idx < 0 or idx >= len(edge) - 1:
                return
            idxs.append(idx)
        self.counts[tuple(idxs)] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []

    # Ensure labels is a dict; if not, treat as empty dict
    if not isinstance(labels, dict):
        labels = {}

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            # Validate key regex
            try:
                if not LABEL_KEY_REGEX.match(key):
                    errors.append(
                        {str(key): f"Label key '{key}' does not match the regex [...]"}
                    )
            except Exception:
                # If regex matching fails due to type mismatch, record error
                errors.append({str(key): 'expected string or bytes-like object'})

        # Validate value(s)
        if isinstance(value, (list, tuple)):
            for elem in value:
                if not isinstance(elem, (str, bytes)):
                    errors.append({str(elem): 'expected string or bytes-like object'})
                else:
                    try:
                        if not LABEL_VALUE_REGEX.match(elem):
                            errors.append(
                                {str(elem): f"Label value '{elem}' does not match the regex [...]"}
                            )
                    except Exception:
                        errors.append({str(elem): 'expected string or bytes-like object'})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                try:
                    if not LABEL_VALUE_REGEX.match(value):
                        errors.append(
                            {str(value): f"Label value '{value}' does not match the regex [...]"}
                        )
                except Exception:
                    errors.append({str(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(errors)

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    # Ensure the value is a string
    if not isinstance(value, str):
        raise ValidationError(f"Expected a string, got {type(value).__name__}")

    # Retrieve the regex pattern from a global variable
    try:
        pattern = REGEX
    except NameError:
        raise ValidationError("No regex pattern defined for validation.")

    if not isinstance(pattern, str):
        raise ValidationError(f"Regex pattern must be a string, got {type(pattern).__name__}")

    # Compile the regex and handle potential errors
    try:
        regex = re.compile(pattern)
    except re.error as exc:
        raise ValidationError(f"Invalid regex pattern: {exc}")

    # Perform a full match to ensure the entire string conforms
    if not regex.fullmatch(value):
        raise ValidationError(f"Value '{value}' does not match the pattern '{pattern}'.")

    return value

def validate_key(key):
    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    # Define the expected pattern: 32 hexadecimal characters (0-9, a-f, A-F)
    # This is a common pattern for keys such as MD5 hashes.
    # If the key is not a string, or does not match the pattern, raise an error.
    try:
        if not isinstance(key, str):
            raise ValueError("Key must be a string")
        if len(key) != 32:
            raise ValueError("Key must be 32 characters long")
        # Check that all characters are valid hexadecimal digits
        for ch in key:
            if ch not in "0123456789abcdefABCDEF":
                raise ValueError(f"Invalid character '{ch}' in key")
    except ValueError as exc:
        # Re-raise as ValidationError if available, otherwise use ValueError
        try:
            # Attempt to use ValidationError if it is defined in the global namespace
            ValidationError
        except NameError:
            # Fallback to ValueError
            raise ValueError(str(exc)) from None
        else:
            raise ValidationError(str(exc)) from None
    # If no exception was raised, the key is considered valid
    return None

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # Ensure we are working with a mutable mapping for the manifest
    if not isinstance(last_applied_manifest, dict):
        # If the manifest is a list, we cannot set keys; skip processing
        return

    for field in observer_schema:
        # Handle nested schema definitions
        if isinstance(field, dict):
            for key, sub_schema in field.items():
                # Initialize nested dict if missing
                if key not in last_applied_manifest:
                    last_applied_manifest[key] = {}
                # Only proceed if the response contains this key
                if key in response:
                    sub_resp = response[key]
                    if isinstance(sub_resp, dict):
                        # Recursively update nested dict
                        update_last_applied_manifest_dict_from_resp(
                            last_applied_manifest[key], sub_schema, sub_resp
                        )
                    elif isinstance(sub_resp, list):
                        # Recursively update nested list
                        update_last_applied_manifest_list_from_resp(
                            last_applied_manifest[key], sub_schema, sub_resp
                        )
        else:
            # Field is a simple key name
            if field not in last_applied_manifest and field in response:
                last_applied_manifest[field] = response[field]

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    if not isinstance(last_applied_manifest, dict):
        raise TypeError("last_applied_manifest must be a dict")
    if not isinstance(observer_schema, dict):
        raise TypeError("observer_schema must be a dict")
    if not isinstance(response, dict):
        raise TypeError("response must be a dict")

    for key, schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Observed field {key!r} not present in response")
        resp_val = response[key]

        if isinstance(schema, dict):
            # Nested dictionary: recurse
            if key not in last_applied_manifest or not isinstance(last_applied_manifest[key], dict):
                last_applied_manifest[key] = {}
            if isinstance(resp_val, dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], schema, resp_val
                )
            else:
                # If the response value is not a dict, just set it
                last_applied_manifest[key] = resp_val
        elif isinstance(schema, list):
            # Nested list: delegate to list handler
            if key not in last_applied_manifest or not isinstance(last_applied_manifest[key], list):
                last_applied_manifest[key] = []
            if isinstance(resp_val, list):
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key], schema, resp_val
                )
            else:
                # If the response value is not a list, just set it
                last_applied_manifest[key] = resp_val
        else:
            # Scalar value: set only if not already present
            if key not in last_applied_manifest

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False
        # Resolve to absolute path if string
        if isinstance(path, str):
            path = os.path.abspath(path)
        # Must be a directory
        if not os.path.isdir(path):
            return False
        # Check for OCFL root marker
        ocfl_root = os.path.join(path, '.ocfl_root')
        if not os.path.exists(ocfl_root):
            return False
        return True
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Validate prefix
    if prefix is None:
        prefix = ''
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    # Retrieve status
    status = getattr(self, 'status', None)
    if status is None:
        return prefix
    # Convert status to string
    if isinstance(status, str):
        status_str = status
    elif isinstance(status, (list, tuple)):
        status_str = ','.join(str(item) for item in status)
    elif hasattr(status, 'name'):
        status_str = status.name
    elif hasattr(status, 'value'):
        status_str = str(status.value)
    else:
        status_str = str(status)
    return f"{prefix}{status_str}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Validate prefix
    if prefix is None:
        prefix = ''
    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")

    # Attempt to retrieve a log attribute
    log = getattr(self, 'log', None) or getattr(self, 'validation_log', None) or getattr(self, '_log', None)

    # If no log is found, return an empty string
    if log is None:
        return ''

    # If the log itself is a string, treat it as a single line
    if isinstance(log, str):
        return f"{prefix}{log}"

    # If the log is bytes, decode it
    if isinstance(log, bytes):
        try:
            log = log.decode('utf-8')
        except Exception:
            log = log.decode('latin1', errors='replace')
        return f"{prefix}{log}"

    # Ensure the log is iterable; if not, convert to string
    try:
        iterator = iter(log)
    except TypeError:
        return f"{prefix}{str(log)}"

    # Build the output lines
    lines = []
    for entry in iterator:
        try:
            line = str(entry)
        except Exception:
            line = repr(entry)
        lines.append(f"{prefix}{line}" if prefix else line)

    return "\n".join(lines)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not manifest_files:
        return
    if digests_used is None:
        digests_used = set()
    elif not isinstance(digests_used, (set, list, tuple)):
        raise TypeError("digests_used must be a set, list, or tuple of digests")
    digests_used = set(digests_used)

    manifest_digests = set()
    for entry in manifest_files:
        # Support dicts with a 'digest' key or tuples/lists where digest is second element
        if isinstance(entry, dict):
            digest = entry.get('digest')
        else:
            try:
                digest = entry[1]
            except Exception:
                raise ValueError(f"Invalid manifest entry format: {entry!r}")
        if not digest:
            continue
        manifest_digests.add(digest)

    missing = manifest_digests - digests_used
    if missing:
        raise ValueError(f"Missing digests that are required but not used: {', '.join(sorted(missing))}")

    unused = digests_used - manifest_digests
    if unused:
        raise ValueError(f"Digests used but not present in manifest: {', '.join(sorted(unused))}")

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic sanity checks
    if prior is None:
        raise ValueError("prior cannot be None")
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}")
    # Ensure required attributes exist
    required_attrs = ('inventory', 'version', 'species', 'parameters')
    for attr in required_attrs:
        if not hasattr(self, attr):
            raise AttributeError(f"self object missing required attribute '{attr}'")
        if not hasattr(prior, attr):
            raise AttributeError(f"prior object missing required attribute '{attr}'")
    # Compare inventories
    try:
        if isinstance(self.inventory, dict) and isinstance(prior.inventory, dict):
            if not set(prior.inventory.keys()).issubset(set(self.inventory.keys())):
                raise ValueError("prior inventory keys are not a subset of current inventory keys")
        else:
            # Assume iterable
            if not set(prior.inventory).issubset(set(self.inventory)):
                raise ValueError("prior inventory items are not a subset of current inventory items")
    except Exception as exc:
        raise ValueError(f"Error comparing inventories: {exc}")
    # Compare versions
    try:
        if prior.version >= self.version:
            raise ValueError("prior version must be older than current version")
    except Exception as exc:
        raise ValueError(f"Error comparing versions: {exc}")
    # Compare species and parameters
    if set(prior.species) != set(self.species):
        raise ValueError("species sets differ between current and prior inventory")
    if set(prior.parameters) != set(self.parameters):
        raise ValueError("parameter sets differ between current and prior inventory")
    # All checks passed
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inputs
    if inventory is None:
        raise ValueError("inventory must not be None")
    if version is None:
        raise ValueError("version must not be None")
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict")

    # If the requested version is not present, return an empty mapping
    if version not in inventory:
        return {}

    # Ensure the mapping for the requested version is a dict
    if not isinstance(inventory[version], dict):
        raise TypeError("inventory[version] must be a dict")

    result = {}

    # Iterate over each logical path in the requested version
    for logical_path, files in inventory[version].items():
        # Convert the files collection to a set (if it isn't already)
        if isinstance(files, (set, list, tuple)):
            files_set = set(files)
        else:
            files_set = {files}

        # Include files from all other versions that reference the same logical path
        for ver, mapping in inventory.items():
            if not isinstance(mapping, dict):
                continue
            if logical_path in mapping:
                other_files = mapping[logical_path]
                if isinstance(other_files, (set, list, tuple)):
                    files_set.update(other_files)
                else:
                    files_set.add(other_files)

        result[logical_path] = files_set

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if not isinstance(manifest_files, (set, list, tuple)):
        raise ValueError("manifest_files must be a set or list")

    # Ensure the required top-level key exists
    if "files" not in fixity:
        raise ValueError("Fixity block missing required 'files' key")

    files = fixity["files"]
    if not isinstance(files, list):
        raise ValueError("'files' must be a list")

    # Convert manifest to a set for fast lookup
    manifest_set = set(manifest_files)

    # Validate each file entry
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each entry in 'files' must be a dictionary")

        # Path must be present and refer to a file in the manifest
        if "path" not in entry:
            raise ValueError("File entry missing required 'path' key")
        path = entry["path"]
        if path not in manifest_set:
            raise ValueError(f"File '{path}' referenced in fixity but not present in manifest")

        # Optional but common fields: hash and size
        if "hash" not in entry:
            raise ValueError(f"File entry for '{path}' missing required 'hash' key")
        if "size" not in entry:
            raise ValueError(f"File entry for '{path}' missing required 'size' key")

        # Basic type validation for hash and size
        if not isinstance(entry["hash"], str):
            raise ValueError(f"Hash for '{path}' must be a string")
        if not isinstance(entry["size"], int):
            raise ValueError(f"Size for '{path}' must be an integer")

    # If all checks pass, return True
    return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        try:
            return [
                os.path.abspath(os.path.join(path, f))
                for f in os.listdir(path)
                if os.path.isfile(os.path.join(path, f))
            ]
        except OSError as exc:
            raise exc
    return []

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise ValueError(f"Provided path '{folder}' is not a directory")

    package_dict = {}
    try:
        # First collect all XML files to identify package basenames
        xml_files = []
        for entry in os.scandir(folder):
            if entry.is_file() and entry.name.lower().endswith('.xml'):
                xml_files.append(entry.name)

        # For each XML file, gather all files with the same basename
        for xml_name in xml_files:
            base_name = os.path.splitext(xml_name)[0]
            files_in_package = []
            for entry in os.scandir(folder):
                if entry.is_file():
                    # Check if the file shares the same basename (ignoring extension)
                    if os.path.splitext(entry.name)[0] == base_name:
                        files_in_package.append(os.path.join(folder, entry.name))
            if files_in_package:
                package_dict[base_name] = files_in_package
    except Exception as e:
        # Log or re-raise as needed; here we simply re-raise
        raise RuntimeError(f"Error exploring folder '{folder}': {e}") from e

    return package_dict

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string")

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            # First pass: identify all XML basenames
            xml_basenames = set()
            for zinfo in zin.infolist():
                if zinfo.is_dir():
                    continue
                base = os.path.basename(zinfo.filename)
                name_no_ext, ext = os.path.splitext(base)
                if ext.lower() == '.xml':
                    xml_basenames.add(name_no_ext)

            # Second pass: collect all files that share an XML basename
            for zinfo in zin.infolist():
                if zinfo.is_dir():
                    continue
                base = os.path.basename(zinfo.filename)
                name_no_ext, _ = os.path.splitext(base)
                if name_no_ext in xml_basenames:
                    if name_no_ext not in result:
                        result[name_no_ext] = {}
                    content = zin.read(zinfo)
                    result[name_no_ext][base] = content
    except (FileNotFoundError, zipfile.BadZipFile):
        # If the file cannot be opened or is not a valid zip, return an empty dict
        return {}

    return result

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`."""
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
            if matches:
                return matches[0]
        except Exception:
            continue
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    Parameters
    ----------
    indent : int, optional
        Number of spaces to use for each indentation level. Must be a
        non‑negative integer. Default is 0 (no indentation).
    debug : bool, optional
        If True, append a debug line containing the object's type and id.
        Default is False.

    Returns
    -------
    str
        A human‑readable, indented representation of the object.
    """
    # Validate parameters
    if not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non‑negative integer")
    if not isinstance(debug, bool):
        raise ValueError("debug must be a boolean")

    # Keep track of visited objects to avoid infinite recursion
    visited = set()

    def _format(obj, level):
        """Recursively format an object with indentation."""
        obj_id = id(obj)
        if obj_id in visited:
            return f"<Circular reference to {type(obj).__name__}>"
        visited.add(obj_id)

        prefix = " " * (level * indent)

        try:
            if isinstance(obj, dict):
                items = []
                for k, v in obj.items():
                    key_repr = repr(k)
                    val_repr = _format(v, level + 1)
                    items.append(f"{prefix}{key_repr}: {val_repr}")
                return "{\n" + ",\n".join(items) + f"\n{prefix}}}"
            elif isinstance(obj, (list, tuple, set, frozenset)):
                open_bracket = "[" if isinstance(obj, list) else "(" if isinstance(obj, tuple) else "{" if isinstance(obj, set) else "{"
                close_bracket = "]" if isinstance(obj, list) else ")" if isinstance(obj, tuple) else "}" if isinstance(obj, set) else "}"
                items = []
                for item in obj:
                    items.append(f"{prefix}{_format(item, level + 1)}")
                return f"{open_bracket}\n" + ",\n".join(items) + f"\n{prefix}{close_bracket}"
            elif isinstance(obj, str):
                return repr(obj)
            elif hasattr(obj, "__dict__") and not isinstance(obj, (int, float, bool, type(None))):
                # Pretty‑print the object's __dict__ if it has one
                return _format(obj.__dict__, level)
            else:
                return repr(obj)
        except Exception as exc:
            return f"<Error formatting object: {exc}>"

    result = _format(self, 0)

    if debug:
        result += f"\n# Debug: type={type(self).__name__}, id={id(self)}"

    return result

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Validate hook
    if hook is None:
        raise ValueError("hook must not be None")
    try:
        hash(hook)
    except Exception as exc:
        raise TypeError("hook must be hashable") from exc

    def decorator(fn):
        if not callable(fn):
            raise TypeError("handler must be callable")
        # Ensure registry exists
        registry = getattr(self, "_registry", None)
        if registry is None:
            registry = {}
            setattr(self, "_registry", registry)
        if not isinstance(registry, dict):
            raise TypeError("registry must be a dict")
        # Add handler
        handlers = registry.setdefault(hook, [])
        if fn in handlers:
            # Duplicate, ignore
            return fn
        handlers.append(fn)
        return fn

    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not callable(namefunc):
        raise TypeError("namefunc must be callable")
    try:
        unicode_type = unicode
    except NameError:
        unicode_type = None

    def wrapper(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
        except Exception as e:
            raise RuntimeError("Error calling namefunc") from e
        if unicode_type is not None and isinstance(result, unicode_type):
            try:
                return result.encode()
            except Exception as e:
                raise RuntimeError("Failed to encode unicode result to bytes") from e
        return result

    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    # Attempt to read a VERSION file in the current working directory
    try:
        with open("VERSION", "r", encoding="utf-8") as f:
            version = f.read().strip()
            if version:
                return version
    except Exception:
        pass

    # Attempt to import a module named 'version' and extract common version attributes
    try:
        import importlib.util
        spec = importlib.util.find_spec("version")
        if spec is not None:
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            for attr in ("__version__", "VERSION", "version"):
                if hasattr(module, attr):
                    value = getattr(module, attr)
                    if isinstance(value, str) and value:
                        return value
    except Exception:
        pass

    # Fallback: try importlib.metadata (Python 3.8+) to get the distribution version
    try:
        from importlib.metadata import version as get_dist_version, PackageNotFoundError
        # Use the current module's name if available
        pkg_name = __package__ or __name__
        try:
            return get_dist_version(pkg_name)
        except PackageNotFoundError:
            pass
    except Exception:
        pass

    # If all attempts fail, return a default string
    return "unknown"

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        # Check if any element in pieces is a plus sign
        if any(p == '+' for p in pieces):
            return '.'
        return '+'
    except TypeError:
        raise ValueError("pieces must be an iterable of characters or strings")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    # Normalize command input
    if isinstance(commands, str):
        # Split the command string into a list of arguments
        cmd_list = commands.split()
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    # Ensure args is a list
    if args is None:
        args = []
    elif not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of strings")

    # Build the full command
    full_cmd = cmd_list + list(args)

    # Prepare environment
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("env must be a dict mapping environment variable names to values")
        env_vars = os.environ.copy()
        env_vars.update(env)
    else:
        env_vars = None

    # Prepare stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None

    # Verbose output
    if verbose:
        print("Running command:", " ".join(full_cmd))

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env_vars,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True,
            check=False
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {full_cmd[0]}") from e
    except OSError as e:
        raise RuntimeError(f"Failed to execute command: {full_cmd}") from e

    if result.returncode != 0:
        raise RuntimeError(
            f"Command '{' '.join(full_cmd)}' exited with non-zero status {result.returncode}"
        )

    return result.stdout

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if not isinstance(vcs, str) or not isinstance(method, str):
            raise TypeError("vcs and method must be strings")
        if not callable(f):
            raise TypeError("decorated object must be callable")
        # Ensure global HANDLERS dict exists
        if 'HANDLERS' not in globals():
            globals()['HANDLERS'] = {}
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Determine the root path for the hierarchy
    try:
        root = getattr(self, 'root_path')
    except AttributeError:
        raise AttributeError("Instance has no 'root_path' attribute for hierarchy validation.")

    # If the root does not exist, nothing to validate
    if not hasattr(os, 'path') or not os.path.exists(root):
        return 0, 0

    # Helper to validate a single object
    def _is_valid(path):
        if not validate_objects:
            return True
        try:
            if hasattr(self, '_validate_object'):
                result = self._validate_object(path)
                return bool(result)
            return True
        except Exception as exc:
            if show_warnings:
                print(f"Warning: validation failed for {path}: {exc}")
            return False

    # Helper to check digest of a single object
    def _digest_ok(path):
        if not check_digests:
            return True
        try:
            if hasattr(self, '_check_digest'):
                result = self._check_digest(path)
                return bool(result)
            return True
        except Exception as exc:
            if show_warnings:
                print(f"Warning: digest check failed for {path}: {exc}")
            return False

    # If root is a file, treat it as a single object
    if os.path.isfile(root):
        num_objects = 1
        good_objects = 1 if _is_valid(root) and _digest_ok(root) else 0
        return num_objects, good_objects

    # If root is a directory, walk through all files
    if os.path.isdir(root):
        num_objects = 0
        good_objects = 0
        for dirpath, dirnames, filenames in os.walk(root):
            for filename in filenames:
                file_path = os.path.join(dirpath, filename)
                num_objects += 1
                if _is_valid(file_path) and _digest_ok(file_path):
                    good_objects += 1
        return num_objects, good_objects

    # If root is neither file nor directory, treat as zero objects
    return 0, 0

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version:
        return "1"
    if not version.isdigit():
        raise ValueError("version must contain only digits")
    try:
        num = int(version)
    except ValueError:
        raise ValueError("invalid numeric value")
    next_num = num + 1
    # Preserve leading zeros if present
    width = len(version)
    next_str = str(next_num).zfill(width)
    return next_str

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError('version_dirs must be a list or tuple of directory names')
    cumulative = {}
    self.different_digests = {}
    base = getattr(self, 'base_dir', os.getcwd())
    for idx, vdir in enumerate(version_dirs, start=1):
        inv_path = os.path.join(base, vdir, 'inventory.json')
        if not os.path.isfile(inv_path):
            raise ValueError(f'Inventory file missing for version {vdir} at {inv_path}')
        try:
            with open(inv_path, 'r', encoding='utf-8') as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f'Failed to load inventory for version {vdir}: {exc}') from exc
        if not isinstance(inv, dict):
            raise ValueError(f'Inventory for version {vdir} must be a mapping')
        # Ensure all previous entries are present
        for path, digest in cumulative.items():
            if path not in inv:
                raise ValueError(f'Inventory for version {vdir} missing entry {path} from previous versions')
        # Record differences with root inventory if available
        root_inv = getattr(self, 'root_inventory', None)
        if isinstance(root_inv, dict):
            for path, digest in inv.items():
                root_digest = root_inv.get(path)
                if root_digest is not None and root_digest != digest:
                    self.different_digests.setdefault(path, []).append(vdir)
        # Update cumulative inventory
        cumulative.update(inv)
    return self

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    if not os.path.exists(path):
        return f"Path does not exist: {path}"
    if os.path.isfile(path):
        return 'file'
    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except OSError as exc:
            return f"Cannot list directory {path}: {exc}"
        # Check for subdirectories that are not Namaste files
        for entry in entries:
            full = os.path.join(path, entry)
            if os.path.isdir(full) and not entry.startswith('0='):
                # Presence of a non‑Namaste subdirectory indicates a root
                return 'root'
        # If no such subdirectory, look for Namaste files
        namaste_files = [e for e in entries if e.startswith('0=') and os.path.isfile(os.path.join(path, e))]
        if namaste_files:
            return 'object'
        # If directory but no Namaste files and no subdirectories, ambiguous

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    if not bug_ids:
        return params
    # Normalize bug_ids to a list
    if isinstance(bug_ids, (int, str)):
        bug_ids = [bug_ids]
    elif isinstance(bug_ids, (list, tuple, set)):
        new_list = []
        for item in bug_ids:
            if hasattr(item, "id"):
                new_list.append(item.id)
            elif hasattr(item, "bug_id"):
                new_list.append(item.bug_id)
            else:
                new_list.append(item)
        bug_ids = new_list
    else:
        raise TypeError("bug_ids must be an int, str, or iterable of ids")
    # If bug_ids is a comma‑separated string, split it
    if isinstance(bug_ids, str):
        bug_ids = [s.strip() for s in bug_ids.split(",") if s.strip()]
    # Convert all ids to strings
    bug_ids = [str(b) for b in bug_ids]
    # Merge with any existing ids in params
    existing = params.get("ids")
    if existing:
        if isinstance(existing, str):
            existing_list = [s.strip() for s in existing.split(",") if s.strip()]
        else:
            existing_list = list(existing)
        combined = list(dict.fromkeys(existing_list + bug_ids))
        params["ids"] = ",".join(combined)
    else:
        params["ids"] = ",".join(bug_ids)
    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from collections import OrderedDict
    try:
        from ruamel.yaml.nodes import MappingNode
    except Exception:
        MappingNode = None

    def merge_mapping_nodes(node1, node2):
        """Recursively merge two MappingNode objects."""
        if not isinstance(node1, MappingNode) or not isinstance(node2, MappingNode):
            return node2
        merged = OrderedDict()
        for k, v in node1.value:
            merged[k.value] = (k, v)
        for k, v in node2.value:
            key = k.value
            if key in merged:
                existing_k, existing_v = merged[key]
                if isinstance(existing_v, MappingNode) and isinstance(v, MappingNode):
                    merged[key] = (existing_k, merge_mapping_nodes(existing_v, v))
                else:
                    merged[key] = (existing_k, v)
            else:
                merged[key] = (k, v)
        return MappingNode(tag=node1.tag, value=list(merged.values()))

    merged_dict = OrderedDict()
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged_dict:
            merged_dict[key] = (key_node, value_node)
        else:
            existing_key_node, existing_value = merged_dict[key]
            if isinstance(existing_value, MappingNode) and isinstance(value_node, MappingNode):
                merged_value = merge_mapping_nodes(existing_value, value_node)
                merged_dict[key] = (existing_key_node, merged_value)
            else:
                merged_dict[key] = (existing_key_node, value_node)
    return [(k_node, v_node) for k_node, v_node in merged_dict.values()]

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    import argparse
    import sys
    parser = argparse.ArgumentParser(description='Parse command-line arguments.')
    # Determine the list of arguments to parse
    if not arguments:
        args_to_parse = sys.argv[1:]
    elif len(arguments) == 1 and isinstance(arguments[0], (list, tuple)):
        args_to_parse = arguments[0]
    else:
        args_to_parse = arguments
    # Ensure all arguments are strings
    try:
        args_to_parse = [str(arg) for arg in args_to_parse]
    except Exception as e:
        raise ValueError(f"Invalid argument types: {e}") from e
    try:
        parsed_args = parser.parse_args(args_to_parse)
        return parsed_args
    except SystemExit as e:
        # argparse uses SystemExit on error; convert to ValueError
        raise ValueError(f"Argument parsing failed: {e}") from e

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate that the input is an ArgumentParser-like object
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    flags = []
    for action in actions:
        # Some actions (e.g., positional arguments) have no option strings
        option_strings = getattr(action, "option_strings", None)
        if option_strings:
            flags.extend(option_strings)

    return " ".join(flags)

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse
    parser = argparse.ArgumentParser()
    try:
        namespace, _ = parser.parse_known_args(list(unparsed_arguments))
    except Exception as e:
        raise ValueError(f"Error parsing arguments: {e}") from e

    # Attempt to detect a subparser name if one was specified
    subparser_name = None
    for attr in ("subparser_name", "command", "subcommand", "subparser"):
        if hasattr(namespace, attr):
            subparser_name = getattr(namespace, attr)
            break

    if subparser_name:
        return {subparser_name: namespace}
    return {"global": namespace}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping name to ArgumentParser")
    if unparsed_arguments is None:
        unparsed_arguments = []
    else:
        unparsed_arguments = list(unparsed_arguments)

    parsed = {}
    remaining_lists = []

    for name, parser in subparsers.items():
        try:
            ns, rem = parser.parse_known_args(unparsed_arguments)
            parsed[name] = ns
            remaining_lists.append(rem)
        except SystemExit:
            # If parsing fails (e.g., due to missing required args), treat as no args claimed
            parsed[name] = None
            remaining_lists.append(unparsed_arguments)

    if remaining_lists:
        # Compute intersection of all remaining lists to find args not claimed by any subparser
        remaining_set = set(remaining_lists[0])
        for rem in remaining_lists[1:]:
            remaining_set &= set(rem)
        remaining_not_claimed = [arg for arg in unparsed_arguments if arg in remaining_set]
    else:
        remaining_not_claimed = unparsed_arguments

    return parsed, remaining_not_claimed

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def _is_mapping(node):
        return hasattr(node, 'tag') and node.tag == 'tag:yaml.org,2002:map'

    def _merge_values(v1, v2):
        if _is_mapping(v1) and _is_mapping(v2):
            return _merge_mapping_nodes(v1, v2)
        # For non-mapping nodes, the last value wins
        return v2

    def _merge_mapping_nodes(n1, n2):
        # Build a dict from the first mapping's key values to (key_node, value_node)
        merged = []
        key_map = {}
        for k_node, v_node in n1.value:
            key_map[k_node.value] = (k_node, v_node)
        # Merge entries from the second mapping
        for k_node, v_node in n2.value:
            key = k_node.value
            if key in key_map:
                existing_k, existing_v = key_map[key]
                merged_v = _merge_values(existing_v, v_node)
                key_map[key] = (existing_k, merged_v)
            else:
                key_map[key] = (k_node, v_node)
        # Preserve the order of the first mapping, then add new entries from the second
        for k_node, _ in n1.value:
            key = k_node.value
            merged.append((k_node, key_map[key][1]))
        for k_node, _ in n2.value:
            key = k_node.value
            if key not in [k.value for k, _ in n1.value]:
                merged.append((k_node, key_map[key][1]))
        # Construct a new MappingNode with the same tag
        return n1.__class__(n1.tag, merged)

    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of (ScalarNode, value) tuples')
    result_map = {}
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError('Each item must be a tuple of (ScalarNode, value)')
        key_node, value_node = item
        key = getattr(key_node, 'value', None)
        if key is None:
            raise ValueError('Key node must have a value attribute')
        if key not in result_map:
            result_map[key] = (key_node, value_node)
        else:
            existing_key_node, existing_value_node = result_map[key]
            merged_value = _merge_values(existing_value_node, value_node)
            result_map[key] = (existing_key_node, merged_value)
    return list(result_map.values())

def parse_arguments(*arguments):
    """
