def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    # Create a top-level parser and a subparsers container with a known destination.
    parser = argparse.ArgumentParser()
    parser.add_subparsers(dest='subparser_name')

    # Normalise the input arguments to a list.
    if unparsed_arguments is None:
        args = []
    else:
        # If a single string is passed, treat it as a single argument.
        if len(unparsed_arguments) == 1 and isinstance(unparsed_arguments[0], str):
            args = [unparsed_arguments[0]]
        else:
            args = list(unparsed_arguments)

    try:
        namespace = parser.parse_args(args)
    except SystemExit as exc:
        # argparse uses SystemExit on parsing errors; convert to a ValueError for callers.
        raise ValueError(f"Argument parsing failed: {exc}") from exc

    # Determine the key for the returned dictionary.
    key = getattr(namespace, 'subparser_name', None)
    if not key:
        key = 'global'

    return {key: namespace}

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise TypeError("size must be a string")
    size = size.strip()
    if not size:
        return 0

    # Separate numeric part and unit part
    num_part = ''
    unit_part = ''
    for i, ch in enumerate(size):
        if ch.isdigit() or ch in '+-.':
            num_part += ch
        else:
            unit_part = size[i:].strip()
            break

    if not num_part:
        raise ValueError(f"Invalid size format: '{size}'")

    try:
        value = float(num_part)
    except ValueError as exc:
        raise ValueError(f"Invalid numeric value in size: '{size}'") from exc

    if not unit_part:
        return int(round(value))

    unit = unit_part.upper()
    # Allow optional trailing 'B'
    if unit.endswith('B'):
        unit = unit[:-1]
    if not unit:
        return int(round(value))

    # Map unit to multiplier (base 1000)
    multipliers = {
        'K': 1000,
        'M': 1000 ** 2,
        'G': 1000 ** 3,
        'T': 1000 ** 4,
        'P': 1000 ** 5,
        'E': 1000 ** 6,
        'Z': 1000 ** 7,
        'Y': 1000 ** 8,
    }

    if unit not in multipliers:
        raise ValueError(f"Unknown unit '{unit_part}' in size: '{size}'")

    return int(round(value * multipliers[unit]))

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        return {}
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("Expected an iterable of dictionaries") from None

    result = {}
    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] += value
                except TypeError:
                    raise TypeError(f"Cannot sum values for key '{key}': {result[key]} + {value}") from None
            else:
                result[key] = value
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Direct None check
    if val is None:
        return True
    # Only consider string-like values
    if isinstance(val, str):
        stripped = val.strip()
        # Empty string is considered None-like
        if not stripped:
            return True
        # Common textual representations of None
        if stripped.lower() in ("none", "null"):
            return True
    return False

