def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two distinct characters")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique characters")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)
    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Basic type validation
    if not isinstance(flow_params, dict):
        raise TypeError(f"flow_params must be a dict, got {type(flow_params).__name__}")
    if not isinstance(register_number, int):
        raise TypeError(f"register_number must be an int, got {type(register_number).__name__}")
    if not isinstance(register_value, str):
        raise TypeError(f"register_value must be a str, got {type(register_value).__name__}")

    def _replace_in_dict(d):
        keys_to_replace = [k for k in d if k == register_value]
        for old_key in keys_to_replace:
            # Preserve the original value
            value = d.pop(old_key)
            # Use register_number as the new key; if it's already present, override
            d[register_number] = value
        # Recurse into nested structures
        for key, val in d.items():
            if isinstance(val, dict):
                _replace_in_dict(val)
            elif isinstance(val, list):
                for item in val:
                    if isinstance(item, dict):
                        _replace_in_dict(item)

    _replace_in_dict(flow_params)
    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class type")
    seen = set()
    queue = [cls]
    while queue:
        c = queue.pop()
        if c in seen:
            continue
        seen.add(c)
        try:
            subs = c.__subclasses__()
        except Exception:
            continue
        for sub in subs:
            if sub not in seen:
                queue.append(sub)
    seen.discard(cls)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate input types
    if not isinstance(string, str):
        raise TypeError(f"string must be of type str, got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")

    # Validate alphabet contents
    if not alphabet:
        raise ValueError("alphabet must contain at least one character")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique characters")
    for idx, ch in enumerate(alphabet):
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError(f"alphabet element at index {idx} is not a single character string")

    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two distinct characters for a valid base")

    # Build mapping from character to its numeric value
    char_to_value = {ch: i for i, ch in enumerate(alphabet)}

    # Convert string to integer
    result = 0
    for pos, ch in enumerate(string):
        if ch not in char_to_value:
            raise ValueError(f"character '{ch}' at position {pos} not found in alphabet")
        result = result * base + char_to_value[ch]

    return result

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Ensure destination path exists and is a directory
    if destination_path.exists():
        if not destination_path.is_dir():
            raise RuntimeError(f"Destination path {destination_path} exists but is not a directory")
    else:
        try:
            destination_path.mkdir(parents=True, exist_ok=True)
        except Exception as exc:
            raise RuntimeError(f"Failed to create destination directory {destination_path}") from exc

    # Download the archive
    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Failed to download archive from {url}") from exc

    # Write to a temporary file
    import tempfile
    import tarfile
    try:
        with tempfile.NamedTemporaryFile(suffix=".tar.gz", delete=False) as tmp_file:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    tmp_file.write(chunk)
            tmp_path = Path(tmp_file.name)
    except Exception as exc:
        raise RuntimeError("Failed to write temporary archive file") from exc

    # Extract the archive
    try:
        with tarfile.open(tmp_path, mode="r:gz") as tar:
            tar.extractall(path=destination_path)
    except Exception as exc:
        raise RuntimeError(f"Failed to extract archive {tmp_path}") from exc
    finally:
        # Clean up the temporary file
        try:
            tmp_path.unlink(missing_ok=True)
        except Exception:
            pass

    return destination_path

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if len(name) < 2:
        return name
    if name[0] == name[-1] and name[0] in ('"', "'", "`"):
        return name[1:-1]
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, str):
        raise TypeError('s must be a string')
    if platform == 'this':
        import sys
        platform = 0 if sys.platform.startswith('win') else 1
    if platform == 1:
        # POSIX: use regex that handles quotes and escapes
        pattern = re.compile(
            r'''(?:"([^"\\]*(?:\\.[^"\\]*)*)"|'([^'\\]*(?:\\.[^'\\]*)*)'|([^ \t\n\r\f\v]+))'''
        )
        args = []
        for m in pattern.finditer(s):
            if m.group(1) is not None:
                token = m.group(1)
            elif m.group(2) is not None:
                token = m.group(2)
            else:
                token = m.group(3)
            # Unescape backslashes and quotes
            token = re.sub(r'\\(.)', r'\1', token)
            args.append(token)
        return args
    elif platform == 0:
        # Windows: simple regex for quoted and unquoted parts
        pattern = re.compile(r'''(?:"([^"]*)"|([^ \t\n\r\f\v]+))''')
        args = []
        for m in pattern.finditer(s):
            if m.group(1) is not None:
                token = m.group(1)
                # Handle escaped quotes and backslashes
                token = token.replace(r'\"', '"').replace(r'\\', '\\')
            else:
                token = m.group(2)
            args.append(token)
        return args
    else:
        raise ValueError('Unsupported platform value: %r' % platform)

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    from pathlib import Path
    import shutil

    # Validate input types
    if not isinstance(archive_path, str):
        raise TypeError(f"archive_path must be a string, got {type(archive_path).__name__}")
    if filename is not None and not isinstance(filename, str):
        raise TypeError(f"filename must be a string or None, got {type(filename).__name__}")
    if not isinstance(tmp_path, (str, Path)):
        raise TypeError(f"tmp_path must be a string or Path, got {type(tmp_path).__name__}")

    archive = Path(archive_path)
    if not archive.is_file():
        raise FileNotFoundError(f"Archive file not found: {archive_path}")

    tmp_dir = Path(tmp_path)
    if not tmp_dir.exists():
        raise FileNotFoundError(f"Temporary path does not exist: {tmp_path}")
    if not tmp_dir.is_dir():
        raise NotADirectoryError(f"Temporary path is not a directory: {tmp_path}")

    # Determine destination directory name
    if filename:
        dest_name = Path(filename).name
    else:
        base = archive.stem
        # Handle common multi‑suffix archives like .tar.gz, .tar.bz2, .tar.xz
        if base.endswith(".tar"):
            base = base.rsplit(".", 1)[0]
        dest_name = base

    dest_dir = tmp_dir / dest_name

    if dest_dir.exists():
        raise FileExistsError(f"Destination directory already exists: {dest_dir}")

    try:
        shutil.unpack_archive(str(archive), str(dest_dir))
    except ValueError as e:
        raise ValueError(f"Unsupported archive format for {archive_path}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to extract archive {archive_path}") from e

    return f"file://{dest_dir.resolve()}"

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        result = subprocess.run(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            capture_output=True,
            text=True,
            check=True
        )
        files = [line.strip() for line in result.stdout.splitlines() if line.strip()]
        files.sort()
        return ','.join(files)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Git command failed: {e.stderr}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error while retrieving ignored files: {e}") from e

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if not isinstance(frequency, str):
        raise ValueError(f"Frequency must be a string or None, got {type(frequency).__name__}")
    freq_str = frequency.strip()
    if not freq_str:
        raise ValueError("Empty frequency string")
    if freq_str.lower() == "always":
        return None
    tokens = freq_str.split()
    if len(tokens) != 2:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")
    number_str, unit = tokens[0], tokens[1].lower()
    try:
        value = float(number_str)
    except ValueError:
        raise ValueError(f"Invalid numeric value in frequency: {number_str!r}")
    if unit in ("day", "days"):
        return datetime.timedelta(days=value)
    if unit in ("hour", "hours"):
        return datetime.timedelta(hours=value)
    if unit in ("minute", "minutes"):
        return datetime.timedelta(minutes=value)
    if unit in ("second", "seconds"):
        return datetime.timedelta(seconds=value)
    if unit in ("week", "weeks"):
        return datetime.timedelta(weeks=value)
    if unit in ("month", "months"):
        return datetime.timedelta(days=value * 30)
    if unit in ("year", "years"):
        return datetime.timedelta(days=value * 365)
    raise ValueError(f"Unknown time unit in frequency: {unit!r}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    import socket
    import ipaddress

    if not host:
        return False

    try:
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False

    for family, _, _, _, sockaddr in infos:
        addr = sockaddr[0]
        try:
            ip = ipaddress.ip_address(addr)
            if ip.is_loopback:
                return True
        except ValueError:
            continue

    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    '''
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise TypeError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    config_path = os.path.expanduser(config_filename)

    # Abort if file exists and overwrite is not allowed
    if not overwrite and os.path.isfile(config_path):
        return

    try:
        dir_name = os.path.dirname(config_path)
        if dir_name:
            os.makedirs(dir_name, exist_ok=True)
        with open(config_path, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
        os.chmod(config_path, mode)
    except OSError as e:
        raise OSError(f"Failed to write configuration to {config_path}: {e}") from e

def oneline(script, separator=" && "):
    """
    Converts a script to a one-line command.
    Useful for running a single SSH command with a one-line script.

    :param script: A string, list/tuple of strings, or any iterable of strings.
    :param separator: The separator to use between commands (default " && ").
    :return: A single-line string representation of the script.
    """
    if script is None:
        return ''
    # Ensure separator is a string
    separator = str(separator) if separator is not None else " && "
    # Helper to process a single string block
    def _process_block(block):
        if isinstance(block, bytes):
            block = block.decode()
        if not isinstance(block, str):
            block = str(block)
        # Dedent to remove common indentation
        block = textwrap.dedent(block)
        # Split into lines, strip whitespace, filter out empty lines
        return [line.strip() for line in block.splitlines() if line.strip()]
    # If script is a string, process directly
    if isinstance(script, str):
        parts = _process_block(script)
    # If script is a list/tuple, process each element
    elif isinstance(script, (list, tuple)):
        parts = []
        for elem in script:
            parts.extend(_process_block(elem))
    # If script is any other iterable (but not a string), process each element
    elif hasattr(script, '__iter__') and not isinstance(script, (bytes, bytearray)):
        parts = []
        for elem in script:
            parts.extend(_process_block(elem))
    # Fallback: convert to string and process
    else:
        parts = _process_block(str(script))
    return separator.join(parts)

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Determine name and default from matcher
    name = None
    default = None

    # Matcher could be a string, tuple/list, dict, or an object with attributes
    if isinstance(matcher, str):
        name = matcher
    elif isinstance(matcher, (tuple, list)):
        if not matcher:
            raise ValueError("Matcher tuple/list must contain at least the variable name")
        name = matcher[0]
        if len(matcher) > 1:
            default = matcher[1]
    elif isinstance(matcher, dict):
        if 'name' not in matcher:
            raise ValueError("Matcher dict must contain a 'name' key")
        name = matcher['name']
        default = matcher.get('default')
    else:
        # Try to get attributes
        try:
            name = getattr(matcher, 'name')
        except AttributeError:
            raise TypeError("Matcher must be a string, tuple/list, dict, or object with a 'name' attribute")
        try:
            default = getattr(matcher, 'default')
        except AttributeError:
            default = None

    if not isinstance(name, str) or not name:
        raise ValueError("Environment variable name must be a non-empty string")

    # Retrieve from environment
    value = os.environ.get(name)
    if value is None:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' not found and no default provided")
    return value

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate inputs
    if commands is None:
        raise ValueError("commands must not be None")
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a string or a list/tuple of strings")
    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of strings")
    if not all(isinstance(a, str) for a in args):
        raise TypeError("all elements in args must be strings")
    if not all(isinstance(c, str) for c in commands):
        raise TypeError("all elements in commands must be strings")

    # Try each command until one succeeds
    for cmd in commands:
        cmd_list = [cmd] + list(args)
        if verbose:
            print(f"Running command: {' '.join(cmd_list)}")
        try:
            result = subprocess.run(
                cmd_list,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                check=True,
                text=True
            )
            return result
        except FileNotFoundError:
            # Command not found, try next
            continue
        except subprocess.CalledProcessError:
            # Command failed, try next
            continue

    # If we reach here, all commands failed
    raise RuntimeError(f"All commands failed: {commands}")

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        if isinstance(target, ipaddress.IPv4Address):
            return True
        ipaddress.IPv4Address(target)
        return True
    except (ValueError, TypeError):
        return False

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        dumper = yaml.SafeDumper
    try:
        yaml_str = yaml.safe_dump(obj, Dumper=dumper, default_flow_style=False)
    except Exception as exc:
        raise
    # In Python 2, yaml.safe_dump returns a byte string; decode to unicode.
    if isinstance(yaml_str, bytes):
        return yaml_str.decode("utf-8")
    return yaml_str

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import logging
    try:
        import yaml
    except ImportError:
        yaml = None
    try:
        import toml
    except ImportError:
        toml = None

    def _expand_env(obj):
        if isinstance(obj, dict):
            return {k: _expand_env(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_expand_env(v) for v in obj]
        if isinstance(obj, str):
            return os.path.expandvars(obj)
        return obj

    configs = {}
    errors = []

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
        except Exception as exc:
            record = logging.LogRecord(
                name=fname,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Failed to read file: {exc}",
                args=None,
                exc_info=(type(exc), exc, exc.__traceback__)
            )
            errors.append(record)
            continue

        ext = os.path.splitext(fname)[1].lower()
        try:
            if ext == '.toml':
                if toml is None:
                    raise ImportError("toml module not available")
                cfg = toml.loads(raw)
            elif ext in ('.yaml', '.yml'):
                if yaml is None:
                    raise ImportError("yaml module not available")
                cfg = yaml.safe_load(raw)
            elif ext == '.json':
                cfg = json.loads(raw)
            else:
                raise ValueError(f"Unsupported file extension: {ext}")
        except Exception as exc:
            record = logging.LogRecord(
                name=fname,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Failed to parse file: {exc}",
                args=None,
                exc_info=(type(exc), exc, exc.__traceback__)
            )
            errors.append(record)
            continue

        if resolve_env:
            try:
                cfg = _expand_env(cfg)
            except Exception as exc:
                record = logging.LogRecord(
                    name=fname,
                    level=logging.ERROR,
                    pathname=fname,
                    lineno=0,
                    msg=f"Failed to expand environment variables: {exc}",
                    args=None,
                    exc_info=(type(exc), exc, exc.__traceback__)
                )
                errors.append(record)
                continue

        if overrides:
            if isinstance(cfg, dict):
                cfg.update(overrides)
            else:
                record = logging.LogRecord(
                    name=fname,
                    level=logging.ERROR,
                    pathname=fname,
                    lineno=0,
                    msg="Overrides provided but configuration is not a dict",
                    args=None,
                    exc_info=None
                )
                errors.append(record)

        configs[fname] = cfg

    return configs, errors

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
    else:
        return obj

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Locate the registry of handlers.  Prefer a dedicated attribute
    # but fall back to common alternatives.
    registry = getattr(cls, "PROTOCOL_HANDLERS", None)
    if registry is None:
        registry = getattr(cls, "HANDLERS", None)
    if registry is None:
        registry = {}

    if not isinstance(registry, dict):
        raise TypeError(
            f"{cls.__name__}.PROTOCOL_HANDLERS must be a dict mapping "
            "version tuples to handler classes"
        )

    # Ensure all keys are tuples; silently ignore non‑tuple keys.
    valid_registry = {k: v for k, v in registry.items() if isinstance(k, tuple)}

    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        return (
            {protocol_version: valid_registry[protocol_version]}
            if protocol_version in valid_registry
            else {}
        )

    # Return a shallow copy to prevent accidental mutation of the
    # internal registry.
    return dict(valid_registry)

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        if values is None:
            raise TypeError("values must be an iterable of strings, got None")
        try:
            iterator = iter(values)
        except TypeError:
            raise TypeError(f"values must be an iterable, got {type(values).__name__}")

        bookmarks = []
        for idx, raw in enumerate(iterator):
            if not isinstance(raw, str):
                raise ValueError(f"Bookmark at index {idx} is not a string: {raw!r}")
            try:
                # Assume Bookmark has a from_raw_value or similar constructor
                bookmark = Bookmark.from_raw_value(raw)
            except Exception as exc:
                raise ValueError(f"Failed to parse bookmark at index {idx} ({raw!r}): {exc}") from exc
            bookmarks.append(bookmark)

        return cls(bookmarks)

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is not __marker:
            return default
        raise
    else:
        del self[key]
        return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the underlying storage exists
    if not hasattr(self, "_data") or not isinstance(self._data, dict):
        raise AttributeError("The object does not have a '_data' dictionary attribute.")
    if not self._data:
        raise KeyError("dict is empty")

    # Determine the key with the lowest frequency
    min_key = None
    min_freq = None
    freq_dict = getattr(self, "_freq", {})
    for key in self._data:
        freq = freq_dict.get(key, 0)
        if min_freq is None or freq < min_freq:
            min_freq = freq
            min_key = key

    # Remove the key from the data store
    value = self._data.pop(min_key)

    # Remove the key from the frequency store if present
    if isinstance(freq_dict, dict):
        freq_dict.pop(min_key, None)

    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Attempt to use an OrderedDict-like cache
    cache = getattr(self, "_cache", None)
    if cache is None:
        raise AttributeError("Cache object does not expose a '_cache' attribute")
    # If the cache supports popitem(last=False), use it
    try:
        return cache.popitem(last=False)
    except TypeError:
        # Fallback: pop the first item in insertion order
        if len(cache) == 0:
            raise KeyError("cache is empty")
        key = next(iter(cache))
        value = cache.pop(key)
        return (key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Use the underlying container that stores the key/value pairs.
    # Prefer an explicit `_dict` attribute if present; otherwise fall back to `self`.
    container = getattr(self, "_dict", self)

    try:
        # OrderedDict supports the `last` keyword; dict does not.
        return container.popitem(last=True)
    except TypeError:
        # Fallback for plain dicts or other mappings that don't accept `last`.
        return container.popitem()
    except KeyError:
        # The container is empty.
        raise KeyError("popitem(): dictionary is empty")

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        # Define a simple identity converter that returns the parameters unchanged.
        def _identity_converter(params):
            return params

        return _converting._Converter(_identity_converter)
    except Exception as exc:
        raise RuntimeError("Failed to create parameter style converter") from exc

def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    _dt = __import__('datetime')
    if timestr is None:
        raise TypeError("timestr must be a string or datetime")
    if isinstance(timestr, _dt.datetime):
        if default is None:
            return timestr
        if not isinstance(default, _dt.datetime):
            raise TypeError("default must be a datetime instance")
        return default.replace(
            year=timestr.year,
            month=timestr.month,
            day=timestr.day,
            hour=timestr.hour,
            minute=timestr.minute,
            second=timestr.second,
            microsecond=timestr.microsecond,
            tzinfo=timestr.tzinfo,
        )
    if not isinstance(timestr, (str, bytes)):
        raise TypeError("timestr must be a string or datetime")
    if isinstance(timestr, bytes):
        timestr = timestr.decode()
    parse_kwargs = {}
    if default is not None:
        parse_kwargs['default'] = default
    if ignoretz:
        parse_kwargs['ignoretz'] = True
    else:
        parse_kwargs['ignoretz'] = False
        if tzinfos is not None:
            parse_kwargs['tzinfos'] = tzinfos
    parse_kwargs.update(kwargs)
    _parse = __import__('dateutil.parser', fromlist=['parse']).parse
    return _parse(timestr, **parse_kwargs)

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    import json
    from xml.etree import ElementTree as etree

    def decode_if_bytes(data):
        return data.decode("utf-8") if isinstance(data, (bytes, bytearray)) else data

    def encode_if_text(data):
        return data.encode("utf-8") if isinstance(data, str) else data

    body = getattr(request, "body", None)
    if body is None:
        return False

    # Check for private JSON payload
    try:
        data = json.loads(decode_if_bytes(body))
        if isinstance(data, dict) and "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass

    # Check for public XML payload
    try:
        xml = etree.fromstring(encode_if_text(body))
        # MAGIC_ENV_TAG should be defined elsewhere in the codebase
        if getattr(xml, "tag", None) == getattr(request, "MAGIC_ENV_TAG", None):
            return True
    except Exception:
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Check the request path for Matrix API prefix
        path = getattr(request, "path", None)
        if isinstance(path, str) and path.startswith("/_matrix/"):
            return True

        # Check headers for typical Matrix indicators
        # Django style headers
        meta = getattr(request, "META", None)
        if isinstance(meta, dict):
            content_type = meta.get("CONTENT_TYPE", "")
            if content_type.startswith("application/json"):
                if meta.get("HTTP_X_MATRIX_REQUEST", "").lower() == "true":
                    return True

        # Flask / generic headers
        headers = getattr(request, "headers", None)
        if headers:
            # headers may be a dict-like object
            content_type = headers.get("Content-Type", "")
            if content_type.startswith("application/json"):
                if headers.get("X-Matrix-Request", "").lower() == "true":
                    return True
            # User-Agent hint
            ua = headers.get("User-Agent", "")
            if "Matrix" in ua:
                return True

    except Exception:
        # Any unexpected error means we cannot confirm a Matrix request
        return False

    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if dt is None:
        raise ValueError("dt must not be None")
    # Obtain the datetime class without a top‑level import
    _datetime = __import__('datetime').datetime
    # If dt is not a datetime instance, try to parse an ISO string
    if not isinstance(dt, _datetime):
        if isinstance(dt, str):
            try:
                dt = _datetime.fromisoformat(dt)
            except Exception:
                raise TypeError("dt must be a datetime instance or an ISO‑formatted string")
        else:
            raise TypeError("dt must be a datetime instance")
    # Convert to UTC
    try:
        offset = dt.tzinfo.utcoffset(dt) if dt.tzinfo else None
    except Exception:
        offset = None
    if offset is None:
        dt_utc = dt
    else:
        dt_utc = dt - offset
    # Format as ISO 8601 with trailing 'Z' to indicate UTC
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    from urllib.parse import urlparse
    from urllib.request import Request, urlopen
    from urllib.error import URLError, HTTPError

    if not isinstance(url, str) or not url:
        return None

    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https"):
        return None

    try:
        req = Request(url, method="HEAD")
        with urlopen(req, timeout=10) as resp:
            return resp.info().get("Content-Type")
    except (URLError, HTTPError, ValueError):
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("'tag' expects a string")
    tag = tag.strip()
    if not tag:
        return False
    if len(tag) > 30:
        return False
    import re
    pattern = re.compile(r'^[A-Za-z0-9_-]+$')
    return bool(pattern.match(tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise TypeError("node cannot be None")
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("node must be an ElementTree element") from exc

    result = {}
    for child in children:
        key = child.tag
        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[key] = [existing, child]
        else:
            result[key] = child
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    result: Dict[str, str] = {}
    try:
        data = json.loads(document)
        # JSON format
        result["subject"] = data.get("subject", "")
        result["aliases"] = data.get("aliases", [])
        links = data.get("links", [])
        for link in links:
            rel = link.get("rel", "")
            href = link.get("href", "")
            if rel == "self":
                result["self_url"] = href
            elif rel == "hcard":
                result["hcard_url"] = href
            elif rel == "profile":
                result["profile_url"] = href
            elif rel == "public-key":
                result["public_key"] = href
            elif rel == "lrdd":
                result["lrdd_url"] = href
            else:
                # store any other rels
                result[rel] = href
        return result
    except (json.JSONDecodeError, TypeError):
        # Try XRD (XML) format
        try:
            root = ET.fromstring(document)
            # Helper to strip namespace
            def _strip_ns(tag: str) -> str:
                return tag.split("}")[-1] if "}" in tag else tag

            subject = ""
            aliases = []
            links = {}
            for elem in root.iter():
                tag = _strip_ns(elem.tag)
                if tag == "Subject":
                    subject = elem.text or ""
                elif tag == "Alias":
                    if elem.text:
                        aliases.append(elem.text)
                elif tag == "Link":
                    rel = elem.attrib.get("rel", "")
                    href = elem.attrib.get("href", "")
                    if rel:
                        links[rel] = href
            result["subject"] = subject
            result["aliases"] = aliases
            for rel, href in links.items():
                if rel == "self":
                    result["self_url"] = href
                elif rel == "hcard":
                    result["hcard_url"] = href
                elif rel == "profile":
                    result["profile_url"] = href
                elif rel == "public-key":
                    result["public_key"] = href
                elif rel == "lrdd":
                    result["lrdd_url"] = href
                else:
                    result[rel] = href
            return result
        except ET.ParseError:
            # Unable to parse document
            return None
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except Exception:
        return None

    # Encode the resource parameter
    try:
        from urllib.parse import quote
    except Exception:
        # Fallback if urllib.parse is not available
        quote = lambda s: s

    resource = f"acct:{handle}"
    encoded_resource = quote(resource, safe="")

    url = f"https://{host}/.well-known/webfinger?resource={encoded_resource}"

    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                return None
            data = resp.read()
            try:
                return data.decode("utf-8")
            except Exception:
                return None
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Validate the handle and extract the host part
    try:
        host = handle.split("@")[1]
    except Exception:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None

    # Attempt to fetch the webfinger document directly
    try:
        document, code, exception = fetch_document(
            host=host,
            path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
        )
    except Exception as exc:
        logger.warning("retrieve_and_parse_diaspora_webfinger: failed to fetch webfinger for %s: %s", handle, exc)
        return None

    if document:
        try:
            return parse_diaspora_webfinger(document)
        except Exception as exc:
            logger.warning("retrieve_and_parse_diaspora_webfinger: failed to parse webfinger for %s: %s", handle, exc)
            return None

    # If the direct webfinger lookup failed, try the host-meta fallback
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None

    # Find the LRDD link in the host-meta
    try:
        link = hostmeta.find_link(rels="lrdd")
    except Exception as exc:
        logger.warning("retrieve_and_parse_diaspora_webfinger: error finding lrdd link in host-meta for %s: %s", host, exc)
        return None

    if not link or not getattr(link, "template", None):
        logger.warning("retrieve_and_parse_diaspora_webfinger: no lrdd template found in host-meta for %s", host)
        return None

    # Construct the LRDD URL and fetch the webfinger document
    try:
        url = link.template.replace("{uri}", quote(handle))
    except Exception as exc:
        logger.warning("retrieve_and_parse_diaspora_webfinger: error constructing lrdd URL for %s: %s", handle, exc)
        return None

    try:
        document, code, exception = fetch_document(url)
    except Exception as exc:
        logger.warning("retrieve_and_parse_diaspora_webfinger: failed to fetch lrdd URL %s: %s", url, exc)
        return None

    if exception or not document:
        return None

    try:
        return parse_diaspora_webfinger(document)
    except Exception as exc:
        logger.warning("retrieve_and_parse_diaspora_webfinger: failed to parse lrdd document for %s: %s", handle, exc)
        return None

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not host:
        return None
    try:
        document, code, exception = fetch_document(host=host, path="/.well-known/host-meta")
    except Exception:
        return None
    if exception or not document:
        return None
    try:
        xrd = XRD.parse_xrd(document)
    except Exception:
        return None
    return xrd

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dict")
    if key is None:
        raise TypeError("key must not be None")
    try:
        hash(key)
    except TypeError:
        raise TypeError(f"key {key!r} is not hashable")
    for k in keys:
        if k is None:
            raise TypeError("sub key must not be None")
        try:
            hash(k)
        except TypeError:
            raise TypeError(f"sub key {k!r} is not hashable")
    if not keys:
        dic[key] = val
        return
    current = dic
    for k in [key] + list(keys[:-1]):
        if k not in current or not isinstance(current[k], dict):
            if k in current and not isinstance(current[k], dict):
                raise TypeError(f"intermediate key {k!r} is not a dict")
            current[k] = {}
        current = current[k]
    current[keys[-1]] = val

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import re
    file_list = []

    # Normalize settings_dirs to a list
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    elif isinstance(settings_dirs, (list, tuple)):
        dirs = list(settings_dirs)
    else:
        # Unsupported type; return empty list
        return []

    for directory in dirs:
        try:
            for fname in os.listdir(directory):
                full_path = os.path.join(directory, fname)
                if not os.path.isfile(full_path):
                    continue

                # If no spec_option provided, include all files
                if not spec_option:
                    file_list.append(full_path)
                    continue

                # Handle spec_option as a string
                if isinstance(spec_option, str):
                    # If it starts with a dot, treat as file extension
                    if spec_option.startswith('.'):
                        if fname.endswith(spec_option):
                            file_list.append(full_path)
                    else:
                        # Treat as a regex pattern
                        try:
                            if re.search(spec_option, fname):
                                file_list.append(full_path)
                        except re.error:
                            # Invalid regex; skip this file
                            continue
                # Handle spec_option as a compiled regex pattern
                elif hasattr(spec_option, 'search'):
                    try:
                        if spec_option.search(fname):
                            file_list.append(full_path)
                    except Exception:
                        continue
                # Unsupported spec_option type; skip
                else:
                    continue
        except OSError:
            # Skip directories that cannot be accessed
            continue

    return sorted(file_list)

