@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content must be provided")

    # If spec_content is bytes, decode to string
    if isinstance(spec_content, (bytes, bytearray)):
        try:
            spec_content = spec_content.decode('utf-8')
        except Exception as e:
            raise IRValidatorException(f"Unable to decode spec content: {e}")

    try:
        data = yaml.safe_load(spec_content)
    except Exception as e:
        raise IRValidatorException(f"Error parsing YAML content: {e}")

    if not isinstance(data, dict):
        raise IRValidatorException("Spec content must be a YAML mapping (dictionary)")

    # Determine required fields; allow subclasses to override
    required_fields = getattr(cls, "REQUIRED_FIELDS", ["name", "type", "spec_version", "data"])

    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields in spec: {', '.join(missing)}")

    return data

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("yaml_file argument must be supplied")

        try:
            with open(yaml_file, 'r', encoding='utf-8') as f:
                data = yaml.safe_load(f)
        except FileNotFoundError as e:
            raise IRValidatorException(f"File not found: {yaml_file}") from e
        except Exception as e:
            raise IRValidatorException(f"Error loading YAML file: {e}") from e

        if data is None:
            raise IRValidatorException("YAML file is empty or could not be parsed")

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file must contain a mapping (dictionary) at the top level")

        # Determine required fields; subclasses may define a class attribute `required_fields`
        required_fields = getattr(cls, 'required_fields', [])
        if not isinstance(required_fields, (list, tuple)):
            raise IRValidatorException("required_fields must be a list or tuple of field names")

        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def _merge_dicts(dest, src):
        for key, val in src.items():
            if key in dest and isinstance(dest[key], dict) and isinstance(val, dict):
                _merge_dicts(dest[key], val)
            else:
                dest[key] = val

    def _resolve(parser_name, seen):
        if parser_name in seen:
            raise RuntimeError(
                f"Circular include detected: {' -> '.join(list(seen) + [parser_name])}"
            )
        seen.add(parser_name)
        parser = parser_dict.get(parser_name)
        if parser is None:
            raise KeyError(f"Parser '{parser_name}' not found for include resolution.")
        includes = parser.get("include")
        if not includes:
            return
        if isinstance(includes, str):
            includes = [includes]
        for inc in includes:
            if inc not in parser_dict:
                raise KeyError(
                    f"Included parser '{inc}' not found for parser '{parser_name}'."
                )
            _resolve(inc, seen)
            _merge_dicts(parser, parser_dict[inc])
        parser.pop("include", None)
        seen.remove(parser_name)

    for pname in list(parser_dict.keys()):
        try:
            _resolve(pname, set())
        except Exception as exc:
            raise RuntimeError(
                f"Error resolving includes for parser '{pname}': {exc}"
            ) from exc
    return None

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Validate spec keys if spec is a dictionary
    if isinstance(self.spec, dict):
        spec_keys = set(self.spec.keys())
        arg_names = {arg.name for arg in self.args if isinstance(arg, _BaseOpt)}
        invalid_keys = spec_keys - arg_names
        if invalid_keys:
            raise errors.InvalidSpecError(f'Invalid spec keys: {invalid_keys}')
    # Build defaults
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue
        # Use value from spec if present
        if isinstance(self.spec, dict) and arg.name in self.spec:
            defaults[arg.name] = self.spec[arg.name]
            continue
        if not isinstance(self.spec, dict) and hasattr(self.spec, arg.name):
            defaults[arg.name] = getattr(self.spec, arg.name)
            continue
        # Fallback to the option's default if it exists
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default
        # Handle nested dictionary options
        if isinstance(arg, DictOption) and arg.scheme:
            nested = arg.scheme.get_spec_defaults()
            if nested:
                defaults[arg.name] = nested
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    # Return a mapping of deprecated argument names to their replacements.
    # This can be overridden by subclasses to provide specific deprecation mappings.
    return {}

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")

    try:
        # Retrieve the command specifications dictionary
        command_specs = getattr(self, "_specs", {})
        if not isinstance(command_specs, dict):
            return None

        # Get the spec for the given command and argument
        spec = command_specs.get(command_name, {}).get(argument_name)
        return spec
    except Exception:
        # In case of any unexpected error, return None
        return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    if args is None:
        return []
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of arguments")
    silent_args = []
    for arg in args:
        if isinstance(arg, str) and arg.startswith('-'):
            silent_args.append(arg)
    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a mapping of argument names to values
    if not isinstance(args, dict):
        raise TypeError("args must be a dict mapping argument names to values")

    # Retrieve the list/set of required argument names; default to empty if not defined
    required = getattr(self, "required_args", [])
    if not required:
        return

    # Identify any missing required arguments
    missing = [name for name in required if name not in args or args[name] is None]

    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # support dict or object
        if isinstance(opt, dict):
            cond = opt.get('required_when')
            name = opt.get('name') or opt.get('arg')
        else:
            cond = getattr(opt, 'required_when', None)
            name = getattr(opt, 'name', None) or getattr(opt, 'arg', None)

        if cond is None or not name:
            continue

        matched = False
        try:
            if callable(cond):
                # try calling with args only
                try:
                    matched = bool(cond(args))
                except TypeError:
                    # try with keyword args
                    matched = bool(cond(command_name=command_name, args=args))
            elif isinstance(cond, str):
                # evaluate string condition in a safe namespace
                matched = bool(eval(cond, {}, {'args': args, 'command_name': command_name}))
            else:
                matched = bool(cond)
        except Exception:
            matched = False

        if matched:
            required.append(name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")
    arg_defs = self.parsed_yaml.get('args', {})
    for arg_name, arg_value in args.items():
        spec = arg_defs.get(arg_name, {})
        if not isinstance(spec, dict):
            continue
        length_spec = spec.get('length')
        if length_spec is None:
            continue
        if not isinstance(length_spec, int):
            raise TypeError(
                f"length for argument '{arg_name}' must be an int, got {type(length_spec).__name__}"
            )
        if length_spec < 0:
            raise ValueError(
                f"length for argument '{arg_name}' must be non-negative, got {length_spec}"
            )
        if arg_value is None:
            continue
        try:
            val_len = len(arg_value)
        except Exception:
            # Value has no length; skip validation for this argument
            continue
        if val_len > length_spec:
            raise ValueError(
                f"Argument '{arg_name}' length {val_len} exceeds maximum {length_spec}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError(
            f"args must be a dict, got {type(args).__name__}"
        )

    # Retrieve argument definitions from the parsed YAML configuration
    arg_defs = self.parsed_yaml.get("args", {})
    if not isinstance(arg_defs, (dict, list)):
        raise TypeError(
            f"Argument definitions must be a dict or list, got {type(arg_defs).__name__}"
        )

    for arg_name, value in args.items():
        # Find the definition for this argument
        arg_def = None
        if isinstance(arg_defs, dict):
            arg_def = arg_defs.get(arg_name)
        else:  # list of dicts
            for item in arg_defs:
                if isinstance(item, dict) and arg_name in item:
                    arg_def = item[arg_name]
                    break

        if arg_def is None:
            # Unknown argument; skip validation
            continue

        # Only validate if 'choices' is defined
        choices = arg_def.get("choices")
        if choices is None:
            continue

        if not isinstance(choices, (list, tuple, set)):
            raise TypeError(
                f"choices for argument '{arg_name}' must be a list, tuple, or set"
            )

        if value not in choices:
            raise ValueError(
                f"Invalid value for argument '{arg_name}': {value!r}. "
                f"Allowed choices: {choices}"
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not hasattr(args, "__iter__"):
        raise TypeError("args must be an iterable of (value, min, max) tuples")
    for idx, item in enumerate(args):
        if not isinstance(item, (list, tuple)):
            raise TypeError(f"Argument at index {idx} must be a tuple/list of (value, min, max)")
        if len(item) != 3:
            raise ValueError(f"Argument at index {idx} must contain exactly 3 elements: (value, min, max)")
        value, min_val, max_val = item
        if min_val > max_val:
            raise ValueError(f"Minimum value {min_val} greater than maximum value {max_val} at index {idx}")
        if not (min_val <= value <= max_val):
            raise ValueError(f"Value {value} at index {idx} is not between {min_val} and {max_val}")
    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non-empty string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dictionary")

    # Determine the base parsing function
    parse_func = spec_option.get("type", str)
    if not callable(parse_func):
        raise TypeError("spec_option['type'] must be callable")

    # Optional validator function
    validator = spec_option.get("validator")
    if validator is not None and not callable(validator):
        raise TypeError("spec_option['validator'] must be callable if provided")

    # Optional set of allowed choices
    choices = spec_option.get("choices")
    if choices is not None and not isinstance(choices, (list, tuple, set)):
        raise TypeError("spec_option['choices'] must be a list, tuple, or set")

    def complex_type(value):
        """Parse and validate a complex argument value."""
        try:
            parsed = parse_func(value)
        except Exception as exc:
            raise ValueError(
                f"Invalid value for option '{option_name}' in subcommand '{subcommand}': {exc}"
            ) from exc

        if choices is not None and parsed not in choices:
            raise ValueError(
                f"Value '{parsed}' for option '{option_name}' not in allowed choices {choices}"
            )

        if validator is not None and not validator(parsed):
            raise ValueError(
                f"Custom validation failed for option '{option_name}' with value '{parsed}'"
            )

        return parsed

    # Attach metadata for debugging / introspection
    complex_type.__name__ = type_name
    complex_type.__doc__ = (
        f"Complex type for option '{option_name}' in subcommand '{subcommand}'. "
        f"Base parser: {parse_func.__name__}"
    )
    return complex_type

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Normalize the input into a dictionary
    if args is None:
        return {}, {}
    if isinstance(args, dict):
        arg_dict = args
    elif isinstance(args, list):
        arg_dict = {}
        for item in args:
            if isinstance(item, dict):
                arg_dict.update(item)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                key, value = item
                if not isinstance(key, str):
                    raise ValueError(f"Argument key must be a string, got {type(key)}")
                arg_dict[key] = value
            else:
                raise ValueError(f"Unsupported list item type: {type(item)}")
    elif hasattr(args, "__dict__"):
        # Handle argparse.Namespace or similar objects
        arg_dict = vars(args)
    else:
        raise TypeError(f"Unsupported args type: {type(args)}")

    control_args = {}
    nested_args = {}

    # Define a simple heuristic for control arguments:
    # keys that start with '_' or 'control_' are considered control.
    for key, value in arg_dict.items():
        if isinstance(key, str) and (key.startswith("_") or key.startswith("control_")):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    if extra_vars is None:
        return vars_dict

    # If extra_vars is a single dictionary, merge it directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict

    # If extra_vars is a list or tuple, iterate over its items
    if isinstance(extra_vars, (list, tuple)):
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                key, value = item
                vars_dict[key] = value
            elif isinstance(item, str):
                # Try to parse a "key=value" string
                if '=' in item:
                    key, value = item.split('=', 1)
                    vars_dict[key] = value
                else:
                    # Unsupported string format; ignore or log
                    pass
            else:
                # Unsupported item type; ignore or log
                pass
        return vars_dict

    # Unsupported type for extra_vars
    raise TypeError("extra_vars must be a dict, list, or tuple")

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    :return: The modified values_dict with converted types
    """
    # Retrieve the parser object for the given command name.
    parser = getattr(self, "parsers", {}).get(parser_name)
    if parser is None:
        raise ValueError(f"Unknown parser name: {parser_name}")

    # Helper to get the option definition from the parser.
    def _get_option(name):
        # Common patterns: parser.options dict or parser.get_option method.
        if hasattr(parser, "options") and isinstance(parser.options, dict):
            return parser.options.get(name)
        if hasattr(parser, "get_option") and callable(parser.get_option):
            return parser.get_option(name)
        return None

    # Iterate over the provided arguments and attempt to cast them.
    for key, raw_value in list(values_dict.items()):
        # Skip if the value is already None or not a string.
        if raw_value is None or not isinstance(raw_value, str):
            continue

        opt = _get_option(key)
        if opt is None:
            # No type information available; leave as is.
            continue

        # Determine the conversion function.
        convert_func = None
        if hasattr(opt, "convert") and callable(opt.convert):
            convert_func = opt.convert
        elif hasattr(opt, "type") and callable(opt.type):
            convert_func = opt.type
        else:
            # Fallback: try to use the type of the default value if present.
            default = getattr(opt, "default", None)
            if default is not None:
                convert_func = type(default)

        if convert_func is None:
            # No conversion possible; skip.
            continue

        try:
            values_dict[key] = convert_func(raw_value)
        except Exception as exc:
            raise ValueError(
                f"Failed to convert argument '{key}' with value '{raw_value}' "
                f"using {convert_func.__name__ if hasattr(convert_func, '__name__') else 'convert'}: {exc}"
            ) from exc

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path")

    # Determine spec file path
    spec_path = os.path.join(plugin_dir, "plugin.json")
    if not os.path.isfile(spec_path):
        # Try YAML if available
        try:
            import yaml  # type: ignore
            spec_path = os.path.join(plugin_dir, "plugin.yaml")
            if not os.path.isfile(spec_path):
                return {}
        except ImportError:
            return {}

    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            if spec_path.endswith(".json"):
                data = json.load(f)
            else:
                # yaml.safe_load may raise if yaml not installed
                data = yaml.safe_load(f)  # type: ignore
    except Exception:
        return {}

    flat: dict[str, object] = {}

    def _flatten(d: dict, parent_key: str = "") -> None:
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten(v, new_key)
            else:
                flat[new_key] = v

    if isinstance(data, dict):
        _flatten(data)

    return flat

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    env_var = 'CONFIG_PATH'
    if env_var not in os.environ:
        if not hasattr(self, 'config_path') or self.config_path is None:
            raise ValueError('config_path attribute is not set')
        os.environ[env_var] = str(self.config_path)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not root:
        raise ValueError("root must not be empty")
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    try:
        rel = os.path.relpath(norm_path, norm_root)
    except ValueError as exc:
        raise ValueError(f"Path '{path}' is not under root '{root}': {exc}") from exc
    if rel.startswith(os.pardir) or rel == os.pardir:
        raise ValueError(f"Path '{path}' is not under root '{root}'")
    return '' if rel == '.' else rel
